134		if err != nil {
135			if errors.Is(err, os.ErrNotExist) {
136				return "", &NotFoundError{Slot: slot}
137			}
138			return "", err
139		}
140		var p slotPointer
141		if err := json.Unmarshal(data, &p); err != nil {
142			return "", &CorruptError{Slot: slot, Reason: "槽指针无法解析"}
143		}
