153	// 成功后返回新记录的标识，记录包含完整世界数据，且没有父记录。
154	func (a *Archive) Save(slot string, w *World) (RecordInfo, error) {
155		if !validSlotName(slot) {
156			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
157		}
158		st := w.Snapshot()
159	
160		lock, err := acquireLock(a.dir)
161		if err != nil {
162			return RecordInfo{}, err
163		}
164		defer lock.release()
165	
166		// 持锁后再次确认槽不存在。
167		if _, err := a.readLatestLocked(slot); err == nil {
168			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
169		} else if !errors.As(err, new(*NotFoundError)) {
