191	}
192	
193	// createSlotPointer 以“临时文件写全 + os.Link 原子建立”的方式创建槽
194	// 指针：Link 在目标已存在时失败，因此重名会被明确拒绝，同时崩溃后
195	// 要么没有该槽，要么指向一份完整记录，绝不会留下半写的指针。
196	func (a *Archive) createSlotPointer(slot string, id RecordID) error {
197		slotsDir := filepath.Join(a.dir, slotsName)
198		final := a.slotPath(slot)
199		data, _ := json.MarshalIndent(slotPointer{Latest: id}, "", "  ")
200	
201		tmp := filepath.Join(slotsDir, ".new-"+slot+"-"+randomSuffix()+".tmp")
202		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o600)
203		if err != nil {
204			return err
205		}
206		if _, err := f.Write(data); err != nil {
207			f.Close()
208			os.Remove(tmp)
209			return err
210		}
211		if err := f.Sync(); err != nil {
212			f.Close()
213			os.Remove(tmp)
214			return err
215		}
216		if err := f.Close(); err != nil {
217			os.Remove(tmp)
218			return err
219		}
220		if err := os.Link(tmp, final); err != nil {
221			os.Remove(tmp)
222			if errors.Is(err, os.ErrExist) {
223				return &ConflictError{Slot: slot, Reason: "存档槽名已存在"}
224			}
225			return err
226		}
227		os.Remove(tmp)
228		return syncDir(slotsDir)
229	}
230	
231	// Replace 用世界当前状态覆盖槽的最新记录。
232	//
233	// expected 必须是调用方此前读到的记录标识，并且它仍是该槽最新记录，
234	// 写入才会发生；否则返回 *ConflictError。新记录的父记录就是被覆盖的
235	// 那次记录。同一目录下并发覆盖同一父记录时只有一个成功。
236	func (a *Archive) Replace(slot string, w *World, expected RecordID) (RecordInfo, error) {
237		if !validSlotName(slot) {
238			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "非法存档槽名"}
239		}
240		if expected == "" {
241			return RecordInfo{}, &ConflictError{Slot: slot, Reason: "覆盖必须提供所依据的记录标识"}
242		}
243		st := w.Snapshot()
244	
245		lock, err := acquireLock(a.dir)
246		if err != nil {
247			return RecordInfo{}, err
248		}
249		defer lock.release()
250	
251		latest, err := a.readLatestLocked(slot)
252		if err != nil {
253			return RecordInfo{}, err
254		}
255		if latest != expected {
256			return RecordInfo{}, &ConflictError{
257				Slot:   slot,
258				Reason: "所依据的记录已不是该槽最新记录",
259			}
260		}
261	
262		id, err := newRecordID()
263		if err != nil {
264			return RecordInfo{}, err
265		}
266		env := &envelope{
267			Format: archiveFormatVersion,
268			ID:     id,
269			Parent: expected,
270			State:  st,
271		}
272		env.Checksum = computeChecksum(env)
273		if err := writeRecord(a.dir, env); err != nil {
274			return RecordInfo{}, err
275		}
276		if err := a.replaceSlotPointer(slot, id); err != nil {
277			return RecordInfo{}, err
278		}
279		return RecordInfo{
280			ID:      id,
281			Parent:  expected,
282			Version: st.Rules.Version,
283		}, nil
284	}
285	
286	func (a *Archive) replaceSlotPointer(slot string, id RecordID) error {
287		data, _ := json.MarshalIndent(slotPointer{Latest: id}, "", "  ")
288		if err := writeAtomic(filepath.Join(a.dir, slotsName), slot+".json", data); err != nil {
289			return err
290		}
291		return nil
292	}
293	
294	// Branch 从 srcSlot 的指定历史记录 src 分出新槽 dstSlot。
295	//
296	// 新槽的首条记录以 src 为父记录，完整复制当时的种子、规则和状态。
297	// 目标槽名已存在时返回 *ConflictError。源记录必须校验通过。
298	func (a *Archive) Branch(srcSlot string, src RecordID, dstSlot string) (RecordInfo, error) {
299		if !validSlotName(srcSlot) {
300			return RecordInfo{}, &ConflictError{Slot: srcSlot, Reason: "非法源存档槽名"}
301		}
302		if !validSlotName(dstSlot) {
303			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "非法目标存档槽名"}
304		}
305		if src == "" {
306			return RecordInfo{}, &NotFoundError{Slot: srcSlot}
307		}
308	
309		lock, err := acquireLock(a.dir)
310		if err != nil {
311			return RecordInfo{}, err
312		}
313		defer lock.release()
314	
315		srcEnv, err := a.loadAndVerifyLocked(src)
316		if err != nil {
317			return RecordInfo{}, err
318		}
319		// 确认源记录确实属于源槽的历史链，避免拿别的槽的记录冒充分支源。
320		if err := a.assertInSlotHistoryLocked(srcSlot, src); err != nil {
321			return RecordInfo{}, err
322		}
323		// 目标槽重名拒绝创建。
324		if _, err := a.readLatestLocked(dstSlot); err == nil {
325			return RecordInfo{}, &ConflictError{Slot: dstSlot, Reason: "目标存档槽名已存在"}
326		} else if !errors.As(err, new(*NotFoundError)) {
327			return RecordInfo{}, err
328		}
329	
330		id, err := newRecordID()
331		if err != nil {
332			return RecordInfo{}, err
333		}
334		env := &envelope{
335			Format:    archiveFormatVersion,
336			ID:        id,
337			Parent:    src,
338			SlotFirst: true,
339			// 完整复制当时的世界数据；此后两槽各自保存互不影响。
340			State: cloneState(srcEnv.State),
341		}
342		env.Checksum = computeChecksum(env)
343		if err := writeRecord(a.dir, env); err != nil {
344			return RecordInfo{}, err
345		}
346		if err := a.createSlotPointer(dstSlot, id); err != nil {
347			return RecordInfo{}, err
348		}
349		return RecordInfo{
350			ID:        id,
351			Parent:    src,
352			SlotFirst: true,
353			Version:   env.State.Rules.Version,
354		}, nil
355	}
356	
357	// assertInSlotHistoryLocked 确认 id 位于 slot 的历史链上（不含越界到
358	// 其他槽的父记录）。
359	func (a *Archive) assertInSlotHistoryLocked(slot string, id RecordID) error {
360		chain, err := a.slotChainLocked(slot)
361		if err != nil {
362			return err
363		}
364		for _, cid := range chain {
365			if cid == id {
366				return nil
367			}
368		}
369		return &NotFoundError{Slot: slot, Record: id}
370	}
371	
372	// slotChainLocked 返回槽的历史记录标识，最新在前，在该槽首条记录处
373	// 停止（不跨入分支来源槽）。
374	func (a *Archive) slotChainLocked(slot string) ([]RecordID, error) {
375		latest, err := a.readLatestLocked(slot)
376		if err != nil {
377			return nil, err
378		}
379		var chain []RecordID
380		seen := map[RecordID]bool{}
381		cur := latest
382		for cur != "" {
383			if seen[cur] {
384				return nil, &CorruptError{Slot: slot, Record: cur, Reason: "历史链出现环"}
385			}
386			seen[cur] = true
387			env, err := loadRecord(recordPath(a.dir, cur))
388			if err != nil {
389				if errors.Is(err, os.ErrNotExist) {
390					return nil, &CorruptError{Slot: slot, Record: cur, Reason: "历史记录文件缺失"}
391				}
392				return nil, &CorruptError{Slot: slot, Record: cur, Reason: err.Error()}
393			}
394			chain = append(chain, cur)
395			if env.SlotFirst {
396				break
397			}
398			cur = env.Parent
399		}
400		return chain, nil
401	}
402	
403	// Slots 返回所有存档槽名。
404	func (a *Archive) Slots() ([]string, error) {
405		entries, err := os.ReadDir(filepath.Join(a.dir, slotsName))
406		if err != nil {
407			return nil, err
408		}
409		var names []string
410		for _, e := range entries {
411			if e.IsDir() {
412				continue
413			}
414			name := e.Name()
415			if len(name) > 5 && name[len(name)-5:] == ".json" {
416				names = append(names, name[:len(name)-5])
417			}
418		}
419		return names, nil
420	}
421

