238			}
239	
240			// 无论本记录是否损坏，槽首记录之后都不再跨入来源槽。
241			if rawErr == nil && raw.SlotFirst {
242				break
243			}
244			if rawErr == nil {
245				cur = raw.Parent
246			} else {
247				cur = ""
248			}
249		}
250	
251		if lastReason == "" {
252			lastReason = "空槽或没有任何历史记录"
253		}
254		return Record{}, &UnrecoverableError{
255			Slot:   slot,
256			Reason: lastReason,
257		}
258	}
