9	// fileLock 是基于 flock 的跨进程互斥锁。同一目录上的多个进程或
10	// 多个实例在同一把锁上排队，保证同一份存档的写入被串行化。
11	type fileLock struct {
12		f *os.File
13	}
14	
15	func acquireLock(dir string) (*fileLock, error) {
16		path := dir + "/lock"
17		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
18		if err != nil {
19			return nil, fmt.Errorf("无法打开存档锁: %w", err)
20		}
21		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
22			f.Close()
23			return nil, fmt.Errorf("无法获取存档锁: %w", err)
24		}
25		return &fileLock{f: f}, nil
26	}
27	
28	func (l *fileLock) release() error {
29		if l == nil || l.f == nil {
30			return nil
31		}
32		_ = syscall.Flock(int(l.f.Fd()), syscall.LOCK_UN)
33		return l.f.Close()
34	}
