11	// TestConcurrentReplaceAcrossProcesses 启动多个进程同时用同一个父记录
12	// 标识覆盖同一槽，要求恰好一个成功，其余全部收到冲突。
13	func TestConcurrentReplaceAcrossProcesses(t *testing.T) {
14		if os.Getenv("WORLD_TEST_HELPER") != "" {
15			t.Skip("子进程模式")
16		}
17		a, dir := newTestArchive(t)
18		w := baseWorld(t)
19		info, err := a.Save("s", w)
20		if err != nil {
21			t.Fatal(err)
22		}
23	
24		const n = 8
25		cmds := make([]*exec.Cmd, n)
26		for i := range cmds {
27			c := exec.Command(os.Args[0], "-test.run=TestMain", "-test.v")
28			c.Env = append(os.Environ(),
29				"WORLD_TEST_HELPER=concurrent_replace",
30				"WORLD_TEST_DIR="+dir,
31				"WORLD_TEST_PARENT="+string(info.ID),
32			)
33			cmds[i] = c
34		}
35	
36		wins, conflicts := 0, 0
37		for _, c := range cmds {
38			err := c.Run()
39			switch {
40			case err == nil:
41				wins++
42			case c.ProcessState.ExitCode() == 3:
43				conflicts++
44			default:
45				t.Fatalf("子进程意外失败: %v", err)
46			}
47		}
48		if wins != 1 || conflicts != n-1 {
49			t.Fatalf("期望恰好 1 成功 %d 冲突，得到 %d 成功 %d 冲突", n-1, wins, conflicts)
50		}
51	
