func (a *Archive) loadLatestVerifiedLocked(slot string) (RecordID, *envelope, error) {
	id, err := a.readLatestLocked(slot)
	if err != nil {
		return "", nil, err
	}
	env, err := a.loadAndVerifyLocked(id)
	if err != nil {
		if ce, ok := err.(*CorruptError); ok {
